// A/B eval harness for the AD SCRIPT flow — the most upstream creative artifact.
//
// WHY THIS EXISTS (workflows/gemini37_adoption.md Slice 4, opened 2026-08-15):
// `adscript` runs on MODEL_TEXT = gemini-3.1-flash-lite, Gemini's CHEAPEST tier.
// Per workflows/cogs_analysis.md, ALL text is <1% of per-ad COGS (~$0.02 of a
// ~$4.96 ad; video is ~90%). So the script — which every downstream stage is
// built on — is being generated by the cheapest available model to save a sum
// that rounds to nothing. This harness measures what that choice actually costs
// in quality before anyone changes a LOCKED model ID.
//
// It replays the REAL tuned adscript flow (buildAdScriptPrompt imported from
// api/_lib/prompts.ts — zero prompt duplication, nothing here is TUNED content)
// against two arms on identical fixed inputs, then writes a side-by-side report
// for a human / gemini-eval to grade.
//
// It does NOT decide a winner. Asserts are STRUCTURAL only. Script quality is
// stochastic and subjective — that is what `gemini-eval` and Neil's eye are for.
//
// Arms are env-configurable:
//   AB_ARM_A — incumbent (default: MODEL_TEXT, i.e. what production runs today)
//   AB_ARM_B — candidate (default: gemini-3.7-flash)
//   AB_SAMPLES — samples per arm per fixture (default 2; script output is
//                stochastic, so one sample per arm proves very little)
//
// Skipped by default — opt in with RUN_AB=1, so `npm test` never burns quota.
//
// Run:
//   $env:RUN_AB='1'; npx vitest run tests/regression/adscript.ab.test.ts --reporter=verbose
//   Override:  $env:AB_ARM_B='gemini-3.6-flash'; $env:AB_SAMPLES='3'
//
// Outputs (.tmp/adscript-ab/): results.json + report.md (full script text on
// both arms, so the two can be read against each other).

import { readFileSync, mkdirSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, it, expect, afterAll } from 'vitest';
import { GoogleGenAI } from '@google/genai';
// Real server-side adscript building blocks (TUNED — imported, NEVER edited here).
import {
  buildAdScriptPrompt,
  parseAdScriptResponse,
  MODEL_TEXT,
  SAFETY_SETTINGS,
} from '../../api/_lib/prompts.js';
import { estimateTextCostUsd } from '../../api/_lib/modelCosts.js';

// --- 1. Load .env manually (no dotenv dep) -------------------------------

const envPath = resolve(process.cwd(), '.env');
try {
  const envText = readFileSync(envPath, 'utf8');
  for (const rawLine of envText.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;
    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) continue;
    const key = line.slice(0, eqIdx).trim();
    let val = line.slice(eqIdx + 1).trim();
    if ((val.startsWith('"') && val.endsWith('"')) || (val.startsWith("'") && val.endsWith("'"))) {
      val = val.slice(1, -1);
    }
    if (!process.env[key]) process.env[key] = val;
  }
} catch {
  /* .env missing — the guard below throws with an explicit message. */
}

// --- 2. Arm configuration -------------------------------------------------

const ARM_A = process.env.AB_ARM_A || MODEL_TEXT; // production today: flash-lite
const ARM_B = process.env.AB_ARM_B || 'gemini-3.7-flash';
const SAMPLES = Math.max(1, Number(process.env.AB_SAMPLES ?? 2));

// Google moved from a numeric `thinkingBudget` to a categorical `thinkingLevel`
// on the 3.6+ generation. The live adscript flow sends thinkingBudget: 4000
// (api/gemini/text.ts), so the candidate arm MUST be mapped or it errors out.
// Approved equivalent for 4000 is 'medium' (workflows/gemini36_adoption.md).
// ⚠️ 3.7 additionally REJECTS thinkingLevel:'minimal' — never emit it here.
const THINKING_LEVEL_MODELS = new Set(['gemini-3.6-flash', 'gemini-3.7-flash']);
const LIVE_THINKING_BUDGET = 4000;

function thinkingConfigFor(model: string): Record<string, unknown> {
  return THINKING_LEVEL_MODELS.has(model)
    ? { thinkingLevel: 'medium' }
    : { thinkingBudget: LIVE_THINKING_BUDGET };
}

const apiKey = process.env.GEMINI_API_KEY;
const ai = apiKey ? new GoogleGenAI({ apiKey }) : null;

// --- 3. Fixtures ----------------------------------------------------------
//
// Copied verbatim from script-gen.regression.test.ts so both harnesses probe the
// same ground. bukidnon is the OFW-coffee baseline the prompt was tuned around;
// cleaning is the deliberate stress case — a SERVICE business that is NOT
// OFW-coffee-shaped, which probes whether the prompt's hardcoded archetypes
// generalize or get copied literally. A weaker model should fail the second one
// first, so keeping both is what makes the comparison informative.

interface BusinessInfoFixture {
  product: string;
  audience: string;
  benefit: string;
  painPoint: string;
  separator: string;
  features: string;
  productImageUrls: any[];
  brandColors: string;
}

const bukidnonFixture: BusinessInfoFixture = {
  product:
    '250g single-origin Bukidnon highland coffee beans, medium roast, resealable valve bag',
  audience: 'OFW wives in Pinas sending pasalubong-style care packages to husbands abroad',
  benefit:
    'Wakes up energized in Saudi, feels closer to pamilya every morning, sweldo stretches further than Saudi cafe runs',
  painPoint:
    '3 AM, hindi makatulog kasi 5 years na siya sa abroad — naiisip na lang kung kayang-kaya pa magtagal',
  separator: 'Direct sa farmer sa Bukidnon, hindi blend ng kung anu-ano',
  features:
    'Single-origin · medium roast · resealable valve bag · 250g · ships internationally',
  productImageUrls: [],
  brandColors: '',
};

const cleaningFixture: BusinessInfoFixture = {
  product: 'Eco-friendly home cleaning service in Metro Manila',
  audience: "Working professionals 28-40 in Makati/BGC who haven't cleaned in 3 weeks",
  benefit:
    'May 4 hours back every weekend, Saturday morning hindi na vacuum-vacuum, may oras for hobbies and family',
  painPoint:
    '3 AM Sunday, hindi makatulog kasi tinatakbo na sa isip ang dapat i-deep clean bago dumating ang bisita on Tuesday',
  separator: 'Plant-based cleaning products, certified safe sa mga bata at pets',
  features:
    'Same-day booking · 2-hour to 5-hour sessions · 100% satisfaction guarantee · Background-checked cleaners',
  productImageUrls: [],
  brandColors: '',
};

const CASES = [
  { label: 'bukidnon-mrbeast', fixture: bukidnonFixture, brand: 'Bukidnon Brew', offer: 'First 50 customers, free shipping + recipe ebook' },
  { label: 'cleaning-mrbeast', fixture: cleaningFixture, brand: 'Kalinis Home', offer: 'First month 20% off, free deep-clean add-on' },
] as const;

// --- 4. Records + objective measures --------------------------------------
//
// These are FACTS about the output, not quality judgements. They exist so the
// report carries something countable next to the prose a human has to read.
// The formula's real rules live in the tuned prompt and are graded by
// gemini-eval — deliberately NOT re-encoded here.

interface Measures {
  hook1Count: number;
  hook2Count: number;
  bodyLines: number;
  avgBodyWords: number;
  longestBodyWords: number;
  auditChars: number;
  /** Hook starvation is a real shipped bug class (issue #59) — worth counting. */
  emptyHooks: boolean;
}

function measure(script: any): Measures {
  const body: string[] = Array.isArray(script?.body) ? script.body : [];
  const words = body.map((l) => String(l).trim().split(/\s+/).filter(Boolean).length);
  const h1 = Array.isArray(script?.hook1) ? script.hook1.length : 0;
  const h2 = Array.isArray(script?.hook2) ? script.hook2.length : 0;
  return {
    hook1Count: h1,
    hook2Count: h2,
    bodyLines: body.length,
    avgBodyWords: words.length ? Number((words.reduce((a, b) => a + b, 0) / words.length).toFixed(1)) : 0,
    longestBodyWords: words.length ? Math.max(...words) : 0,
    auditChars: typeof script?.strategicAudit === 'string' ? script.strategicAudit.length : 0,
    emptyHooks: h1 === 0 || h2 === 0,
  };
}

interface Record_ {
  caseLabel: string;
  arm: 'A' | 'B';
  model: string;
  sample: number;
  latencyMs: number | null;
  usage: Record<string, number | undefined>;
  estUsd: number | null;
  parsedOk: boolean;
  measures: Measures | null;
  script: unknown;
  error?: string;
}
const results: Record_[] = [];

// --- 5. One generation, against the REAL tuned prompt ---------------------
//
// This mirrors api/gemini/text.ts FLOW_REGISTRY.adscript (build -> generate ->
// parse) with the model as the ONLY variable, including its hook-starvation
// retry (issue #59) so both arms get production's real second chance.
// Deliberately calls the SDK directly instead of going through
// services/geminiService — the client wrapper only forwards {flow, input} and
// the model is chosen server-side, so there is nothing to swap at that layer.

async function generateOnce(
  model: string,
  fixture: BusinessInfoFixture,
  brand: string,
  offer: string
): Promise<{ script: any; latencyMs: number; usage: any }> {
  if (!ai) throw new Error('adscript.ab: GEMINI_API_KEY missing from .env');
  const input = {
    businessInfo: { ...fixture, scriptType: 'MrBeast' },
    brandName: brand,
    language: 'Taglish',
    offer,
    chosenAngleBrief: '',
    contrarianTruth: '',
  };
  const prompt = buildAdScriptPrompt(input as any, undefined, undefined);

  let usage: any = {};
  const t0 = performance.now();
  const run = async () => {
    const response: any = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        safetySettings: SAFETY_SETTINGS,
        thinkingConfig: thinkingConfigFor(model),
      },
    } as any);
    usage = response.usageMetadata ?? {};
    return parseAdScriptResponse(response.text || '{}');
  };
  let script = await run();
  // Production regenerates once when the hooks come back empty; mirror it so a
  // model is not penalised for a retry production would have given it.
  if (!(script?.hook1?.length && script?.hook2?.length)) {
    script = await run().catch(() => script);
  }
  return { script, latencyMs: performance.now() - t0, usage };
}

async function runArm(caseLabel: string, arm: 'A' | 'B', model: string, sample: number, c: (typeof CASES)[number]) {
  let rec: Record_;
  try {
    const { script, latencyMs, usage } = await generateOnce(model, c.fixture, c.brand, c.offer);
    rec = {
      caseLabel,
      arm,
      model,
      sample,
      latencyMs,
      usage: {
        promptTokenCount: usage.promptTokenCount,
        candidatesTokenCount: usage.candidatesTokenCount,
        thoughtsTokenCount: usage.thoughtsTokenCount,
        totalTokenCount: usage.totalTokenCount,
      },
      estUsd: estimateTextCostUsd(model, usage),
      parsedOk: Array.isArray(script?.hook1) && Array.isArray(script?.body) && script.body.length > 0,
      measures: measure(script),
      script,
    };
  } catch (e: any) {
    rec = {
      caseLabel, arm, model, sample,
      latencyMs: null, usage: {}, estUsd: null,
      parsedOk: false, measures: null, script: null,
      error: e?.message ? String(e.message) : String(e),
    };
  }
  results.push(rec);
  return rec;
}

// --- 6. Report ------------------------------------------------------------

function fmt(n: number | null | undefined, d = 0) {
  return n == null || Number.isNaN(n) ? '—' : n.toFixed(d);
}

function writeReports() {
  const outDir = resolve(process.cwd(), '.tmp/adscript-ab');
  mkdirSync(outDir, { recursive: true });
  writeFileSync(
    resolve(outDir, 'results.json'),
    JSON.stringify({ ranAt: new Date().toISOString(), armA: ARM_A, armB: ARM_B, samples: SAMPLES, results }, null, 2)
  );

  const L: string[] = [];
  L.push('# Ad Script A/B Eval');
  L.push('');
  L.push(`Ran at: ${new Date().toISOString()}`);
  L.push('');
  L.push(`- Arm A: \`${ARM_A}\` (incumbent — what production runs today)`);
  L.push(`- Arm B: \`${ARM_B}\` (candidate)`);
  L.push(`- Samples per arm per case: ${SAMPLES}`);
  L.push('');
  L.push('⚠️ Structural asserts only. This report does NOT pick a winner — read the');
  L.push('scripts and grade with `gemini-eval`. The numbers below are countable facts,');
  L.push('not quality scores.');
  L.push('');

  const totals: Record<string, { usd: number; ms: number; n: number; empty: number }> = {};
  for (const r of results) {
    const k = r.arm;
    totals[k] ??= { usd: 0, ms: 0, n: 0, empty: 0 };
    totals[k].usd += r.estUsd ?? 0;
    totals[k].ms += r.latencyMs ?? 0;
    totals[k].n += 1;
    if (r.measures?.emptyHooks) totals[k].empty += 1;
  }
  L.push('## Totals');
  L.push('');
  L.push('| Arm | Model | Calls | Total est USD | Avg latency | Empty-hook runs |');
  L.push('|---|---|---|---|---|---|');
  for (const arm of ['A', 'B'] as const) {
    const t = totals[arm];
    if (!t) continue;
    L.push(`| ${arm} | \`${arm === 'A' ? ARM_A : ARM_B}\` | ${t.n} | $${t.usd.toFixed(5)} | ${fmt(t.ms / t.n)}ms | ${t.empty}/${t.n} |`);
  }
  L.push('');

  for (const c of CASES) {
    L.push(`## ${c.label}`);
    L.push('');
    L.push('| Arm | Sample | Latency | In tok | Out tok | Thoughts | Est USD | hooks 1/2 | body | avg words | longest | audit chars | ok |');
    L.push('|---|---|---|---|---|---|---|---|---|---|---|---|---|');
    for (const r of results.filter((x) => x.caseLabel === c.label)) {
      const m = r.measures;
      L.push(
        `| ${r.arm} | ${r.sample} | ${fmt(r.latencyMs)}ms | ${fmt(r.usage.promptTokenCount)} | ${fmt(r.usage.candidatesTokenCount)} | ` +
          `${fmt(r.usage.thoughtsTokenCount)} | ${r.estUsd != null ? '$' + r.estUsd.toFixed(5) : '—'} | ` +
          `${m ? `${m.hook1Count}/${m.hook2Count}` : '—'} | ${m ? m.bodyLines : '—'} | ${m ? m.avgBodyWords : '—'} | ` +
          `${m ? m.longestBodyWords : '—'} | ${m ? m.auditChars : '—'} | ${r.parsedOk}${r.error ? ' ' + r.error.slice(0, 60) : ''} |`
      );
    }
    L.push('');
    for (const r of results.filter((x) => x.caseLabel === c.label)) {
      L.push(`### ${c.label} — Arm ${r.arm} (\`${r.model}\`) sample ${r.sample}`);
      L.push('');
      L.push('```json');
      L.push(JSON.stringify(r.script ?? { error: r.error }, null, 2).slice(0, 4000));
      L.push('```');
      L.push('');
    }
  }
  writeFileSync(resolve(outDir, 'report.md'), L.join('\n'));
}

// --- 7. The runs ----------------------------------------------------------

const SHOULD_RUN = !!process.env.RUN_AB;

afterAll(() => {
  if (SHOULD_RUN && results.length) writeReports();
});

describe.skipIf(!SHOULD_RUN)(`Ad script A/B (${ARM_A} vs ${ARM_B})`, () => {
  for (const c of CASES) {
    it(
      c.label,
      async () => {
        for (let s = 1; s <= SAMPLES; s++) {
          const a = await runArm(c.label, 'A', ARM_A, s, c);
          const b = await runArm(c.label, 'B', ARM_B, s, c);
          // Structural only: each arm either errored or produced a usable Script.
          // Never assert that B beats A — that is the human's call.
          expect(a.error != null || a.parsedOk).toBe(true);
          expect(b.error != null || b.parsedOk).toBe(true);
        }
      },
      600_000
    );
  }
});
